export function buildRoomOne({THREE,scene,box,sphere,solid,colliders}){const H=4.2;
 const door=solid(.15,3,1.9,0x42382e,-3.05,H+1.5,-.5);door.userData.dynamic=true;
 const canvas=document.createElement('canvas');canvas.width=256;canvas.height=384;const ctx=canvas.getContext('2d');ctx.fillStyle='#851d20';ctx.font='bold 270px serif';ctx.textAlign='center';ctx.fillText('1',128,280);for(const [x,y,h]of [[105,257,48],[145,266,32],[166,255,59]])ctx.fillRect(x,y,4,h);const texture=new THREE.CanvasTexture(canvas);texture.colorSpace=THREE.SRGBColorSpace;for(const side of [-1,1]){const number=new THREE.Mesh(new THREE.PlaneGeometry(.65,1),new THREE.MeshBasicMaterial({map:texture,transparent:true,depthWrite:false}));number.name='Red number one on door';number.rotation.y=side*Math.PI/2;number.position.set(side*.081,0,0);door.add(number);}const barrier=colliders[colliders.length-1];
 const key=new THREE.Group();key.name='Room one silver key';scene.add(key);const silver=new THREE.MeshStandardMaterial({color:0xb7c9cb,metalness:.65,roughness:.3});key.add(new THREE.Mesh(new THREE.TorusGeometry(.08,.02,8,16),silver));box(.035,.22,.03,silver,0,-.15,0,key);box(.08,.03,.03,silver,.025,-.23,0,key);key.position.set(-11.5,H+.06,2.4);key.rotation.x=-Math.PI/2;
 const doll=new THREE.Group();doll.name='Room one hanging doll';doll.position.set(-11,H+2.5,-3);scene.add(doll);box(.015,.75,.015,0x817864,0,-.35,0,doll);sphere(.19,0xb9ae94,0,-.9,0,doll);box(.28,.42,.19,0x625b50,0,-1.25,0,doll);for(const side of [-1,1]){sphere(.04,0x172321,side*.07,-.88,.17,doll);box(.07,.38,.08,0x625b50,side*.21,-1.25,0,doll);box(.08,.3,.09,0x625b50,side*.09,-1.6,0,doll);}
 const hand=new THREE.Group();hand.name='Hand beneath bedroom bed';hand.position.set(-7.45,.12,9.7);scene.add(hand);sphere(.17,0x7d8072,0,0,0,hand,1,.4,1.2);for(let i=0;i<4;i++){const finger=box(.045,.06,.29,0x7d8072,(i-1.5)*.073,0,.19,hand);finger.rotation.y=(i-1.5)*.13;}box(.13,.07,.27,0x4c5149,0,0,-.19,hand);
 const glass=new THREE.MeshStandardMaterial({color:0x8ba3a4,metalness:.7,roughness:.25,side:THREE.DoubleSide});for(let i=0;i<12;i++){const x=-11.6+(i%4)*.3,z=-2.4+Math.floor(i/4)*.35;const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute([x,H+.025,z,x+.22,H+.025,z+.12,x-.05,H+.025,z+.28],3));g.computeVertexNormals();scene.add(new THREE.Mesh(g,glass));}
 return{door,barrier,key,doll,hand,reset(){door.visible=true;door.rotation.y=0;barrier.top=H+3;key.visible=true;},update(t){doll.rotation.z=Math.sin(t*.9)*.09;hand.position.z=9.7+Math.sin(t*.45)*.06;}};
}
